from pathlib import Path
import subprocess as sp,json,random,statistics,fcntl,hashlib
p=Path(__file__).parent;vs=['baseline','control','medium'];builds=[]
for cfg,opts in [('default',[]),('native',['-march=native'])]:
 for v in ['baseline','medium']:
  cmd=['taskset','-c','6','/usr/bin/g++','-O2','-std=c++23','-DSKIP_RUNTIME_CHECKS',*opts,'-DHEADER="'+str(p/((v if v!='control'else'baseline')+'.hpp'))+'"',str(p/'enum_bench.cpp'),'-o',str(p/f'enum-{cfg}-{v}')];a=sp.run(cmd,capture_output=True,text=True);assert a.returncode==0,a.stderr;builds.append(dict(v=v,cfg=cfg,cmd=cmd,sha=hashlib.sha256((p/(v+'.hpp')).read_bytes()).hexdigest(),stderr=a.stderr))
raw=[];rng=random.Random(20261028);cases=[(128,5000),(16384,500),(100000,100),(1000000,20),(1500000,10),(2000000,10),(10000000,3),(100000000,1),(500000000,1)]
with open('/tmp/sirkit_performance_cpu14.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for rep in range(5):
  for cfg in ['default','native']:
   for n,reps in cases:
    for mode in [0,1]:
     order=vs[:];rng.shuffle(order);checks=[]
     for v in order:
      out=sp.check_output(['taskset','-c','14',str(p/(f'enum-{cfg}-'+('baseline'if v=='control'else v))),str(n),str(mode),str(reps)],text=True).split();checks.append(out[1]);raw.append(dict(rep=rep,cfg=cfg,n=n,mode=mode,v=v,ns=float(out[0]),checksum=out[1]))
     assert len(set(checks))==1,(cfg,n,mode,checks)
  (p/'medium-raw.json').write_text(json.dumps(dict(builds=builds,raw=raw),indent=2));print(rep,flush=True)
summary=[]
for cfg in ['default','native']:
 for n,_ in cases:
  for mode in [0,1]:
   med={v:statistics.median(x['ns']for x in raw if (x['cfg'],x['n'],x['mode'],x['v'])==(cfg,n,mode,v))for v in vs};summary.append(dict(cfg=cfg,n=n,mode=mode,med=med,ratio={v:t/med['baseline']for v,t in med.items()}))
(p/'medium-summary.json').write_text(json.dumps(summary,indent=2))

