for flags,mode in [([], 'default'),(['-march=native'],'native')]:
 for v in variants:
  cmd=['taskset','-c','8','/usr/bin/g++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',*flags,'-DHEADER="'+str(p/(v+'.hpp'))+'"',str(p/'api.cpp'),'-o',str(p/(mode+'_api_'+v))];q=sp.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr;builds.append(dict(cmd=cmd,diagnostics=q.stderr,source_sha256=hashlib.sha256((p/(v+'.hpp')).read_bytes()).hexdigest()))
with open('/tmp/sirkit_performance_cpu4.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for n in [127,3969,16384,32767,32768,1000000,100000000]:
  for mode in ['default','native']:
   for op in range(4):
    reps=max(2,min(10000,1000000//max(1,n))) if op!=1 else max(2,min(100000,20000000//max(1,n//128)))
    for rep in range(7):
     vs=['baseline','control','carry_clean'];rng.shuffle(vs)
     for v in vs:
