from pathlib import Path
import subprocess as sp,json,hashlib,statistics as st,random,fcntl
p=Path(__file__).parent;variants=['baseline','soa','prime32_safe'];sha=lambda x:hashlib.sha256(x.read_bytes()).hexdigest();commands=[]
for v in variants:
 cmd=['taskset','-c','6','/usr/bin/g++','-O2','-march=native','-std=c++23','-DSKIP_RUNTIME_CHECKS','-DHEADER="'+str(p/(v+'.hpp'))+'"',str(p/'bench.cpp'),'-o',str(p/('native_'+v))];q=sp.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr;commands.append(dict(variant=v,cmd=cmd,header_sha256=sha(p/(v+'.hpp')),binary_sha256=sha(p/('native_'+v))))
rows=[];checks={};rng=random.Random(20261028)
with open('/tmp/sirkit_performance_cpu12.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for n in [100000,1000000,10000000,100000000,1000000000]:
  reps=max(1,10000000//n)
  for rep in range(5):
   vs=variants+['control'];rng.shuffle(vs)
   for v in vs:
    exe=p/('native_'+('baseline'if v=='control'else v));q=sp.run(['taskset','-c','12',str(exe),str(n),'0',str(reps)],capture_output=True,text=True);assert q.returncode==0,q.stderr;t,c=q.stdout.split();assert n not in checks or checks[n]==c,(n,v,c,checks.get(n));checks[n]=c;rows.append(dict(n=n,mode=0,rep=rep,variant=v,ns=float(t),checksum=c))
  (p/'soa-results.json').write_text(json.dumps(dict(commands=commands,raw=rows),indent=2));print(n,flush=True)
summary={}
for n in checks:
 m={v:st.median(x['ns']for x in rows if x['n']==n and x['variant']==v)for v in variants+['control']};summary[n]={'baseline_ns':m['baseline'],**{v:t/m['baseline']for v,t in m.items()}}
(p/'soa-summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))
